class TicTacToe {
    private int n;
    private int[] rows;
    private int[] cols;
    private int diag;
    private int antiDiag;

    public TicTacToe(int n) {
        this.n = n;
        this.rows = new int[n];
        this.cols = new int[n];
        this.diag = 0;
        this.antiDiag = 0;
    }

    public int move(int row, int col, int player) {
        int val = (player == 1) ? 1 : -1;
        rows[row] += val;
        cols[col] += val;
        if (row == col) diag += val;
        if (row + col == n - 1) antiDiag += val;
        if (Math.abs(rows[row]) == n || Math.abs(cols[col]) == n || Math.abs(diag) == n || Math.abs(antiDiag) == n) {
            return player;
        }
        return 0;
    }
}

/**
 * @param {number} n
 */
var TicTacToe = function(n) {
    this.n = n;
    this.rows = new Array(n).fill(0);
    this.cols = new Array(n).fill(0);
    this.diag = 0;
    this.antiDiag = 0;
};

/** 
 * @param {number} row 
 * @param {number} col 
 * @param {number} player
 * @return {number}
 */
TicTacToe.prototype.move = function(row, col, player) {
    const val = player === 1 ? 1 : -1;
    this.rows[row] += val;
    this.cols[col] += val;
    if (row === col) this.diag += val;
    if (row + col === this.n - 1) this.antiDiag += val;
    if (Math.abs(this.rows[row]) === this.n ||
        Math.abs(this.cols[col]) === this.n ||
        Math.abs(this.diag) === this.n ||
        Math.abs(this.antiDiag) === this.n) {
        return player;
    }
    return 0;
};
